using GraphApi.Models.ENC.OpcionesPregunta;namespace GraphApi.Services.ENC.OpcionesPregunta{    /// <summary>    /// Define las operaciones de negocio y persistencia para OpcionesPreguntas.    /// </summary>    public interface IOpcionesPreguntaService    {        /// <summary>        /// Obtiene la lista de OpcionesPreguntas con filtros opcionales.        /// </summary>        /// <param name="userId">ID de usuario (cabecera “UserID”).</param>        /// <param name="windowName">Nombre de aplicación (cabecera “WindowName”).</param>        Task<IEnumerable<clReadOpcionesPregunta>> GetOpcionesPreguntas(            int userId,            string windowName);        /// <summary>        /// Obtiene la lista dinámica de OpcionesPreguntas con filtros opcionales.        /// </summary>        /// <param name="opcionPreguntaID">Filtro opcional para OpcionPreguntaID.</param>        /// <param name="preguntaID">Filtro opcional para PreguntaID.</param>        /// <param name="texto">Filtro opcional para Texto.</param>        /// <param name="valor">Filtro opcional para Valor.</param>        /// <param name="orden">Filtro opcional para Orden.</param>        /// <param name="bEliminado">Filtro opcional para bEliminado.</param>        /// <param name="columnNames">Nombres de columnas a retornar (separados por coma). Si es null o vacío, retorna columna por defecto.</param>        /// <param name="userId">ID de usuario (cabecera “UserID”).</param>        /// <param name="windowName">Nombre de aplicación (cabecera “WindowName”).</param>        Task<IEnumerable<dynamic>> GetOpcionesPreguntasDynamic(            int? opcionPreguntaID,            int? preguntaID,            string? texto,            string? valor,            int? orden,            bool? bEliminado,            string? columnNames,            int userId,            string windowName);        /// <summary>        /// Crea un nuevo OpcionesPregunta.        /// </summary>        /// <param name="objInput">Datos para crear el OpcionesPregunta.</param>        /// <param name="userId">ID de usuario (cabecera “UserID”).</param>        /// <param name="windowName">Nombre de aplicación (cabecera “WindowName”).</param>        Task<clReadOpcionesPregunta> CreateOpcionesPregunta(            clCreateOpcionesPregunta objInput,            int userId,            string windowName);        /// <summary>        /// Actualiza campos selectivos de un OpcionesPregunta.        /// </summary>        /// <param name="objInput">Datos para actualizar el OpcionesPregunta, incluyendo su ID y campos a modificar.</param>        /// <param name="userId">ID de usuario (cabecera “UserID”).</param>        /// <param name="windowName">Nombre de aplicación (cabecera “WindowName”).</param>        Task<clReadOpcionesPregunta?> UpdateOpcionesPregunta(            clUpdateOpcionesPregunta objInput,            int userId,            string windowName);        /// <summary>        /// Elimina un OpcionesPregunta por su ID.        /// </summary>        /// <param name="nOpcionesPreguntaID">ID del OpcionesPregunta a eliminar.</param>        Task<bool> DeleteOpcionesPregunta(int nOpcionesPreguntaID);    }}